export type ParsedClaimInstruction<
  TProgram extends string = typeof HEIRLOOM_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    heir: TAccountMetas[0];
    authority: TAccountMetas[1];
    delegate?: TAccountMetas[2] | undefined;
    heirTokenAccount?: TAccountMetas[3] | undefined;
    estate: TAccountMetas[4];
    vault: TAccountMetas[5];
    vaultTokenAccount?: TAccountMetas[6] | undefined;
    mint?: TAccountMetas[7] | undefined;
    /**
     * Proves `mint` was actually registered as a claimable asset for this
     * estate, rather than an arbitrary vault-owned token account.
     */
    assetRecord?: TAccountMetas[8] | undefined;
    treasury: TAccountMetas[9];
    treasuryTokenAccount?: TAccountMetas[10] | undefined;
    tokenProgram: TAccountMetas[11];
    associatedTokenProgram: TAccountMetas[12];
    systemProgram: TAccountMetas[13];
  };
  data: ClaimInstructionData;
};

export function parseClaimInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedClaimInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 14) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 14,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === HEIRLOOM_PROGRAM_ADDRESS ? undefined : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      heir: getNextAccount(),
      authority: getNextAccount(),
      delegate: getNextOptionalAccount(),
      heirTokenAccount: getNextOptionalAccount(),
      estate: getNextAccount(),
      vault: getNextAccount(),
      vaultTokenAccount: getNextOptionalAccount(),
      mint: getNextOptionalAccount(),
      assetRecord: getNextOptionalAccount(),
      treasury: getNextAccount(),
      treasuryTokenAccount: getNextOptionalAccount(),
      tokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getClaimInstructionDataDecoder().decode(instruction.data),
  };
}
